 private static final String OWNER="com.android.systemui.statusbar.phone.NotificationIconContainer",ICON="com.android.systemui.statusbar.StatusBarIconView",ROOT="com.android.systemui.statusbar.phone.PhoneStatusBarView";
 private static final Map<ViewGroup,Boolean> owners=new WeakHashMap<>();private static final List<XC_MethodHook.Unhook> hooks=new ArrayList<>();private static Class<?> ownerType,iconType;private static boolean ready,active,failed;private static int count,limit,draws;private static long generation;
 private static boolean main(){return Looper.myLooper()==Looper.getMainLooper();}
 static void install(ClassLoader loader){try{Class<?> owner=XposedHelpers.findClass(OWNER,loader),icon=XposedHelpers.findClass(ICON,loader);if(owner.getSuperclass()!=ViewGroup.class||owner.getDeclaredMethod("shouldForceOverflow",int.class,int.class,float.class,int.class).getReturnType()!=boolean.class||icon.getDeclaredMethod("getVisibleState").getReturnType()!=int.class)throw new IllegalStateException();owner.getDeclaredField("mIconStates");owner.getDeclaredField("mIsolatedIcon");owner.getDeclaredMethod("updateState");XposedBridge.hookMethod(owner.getDeclaredMethod("calculateIconXTranslations"),new XC_MethodHook(){@Override protected void afterHookedMethod(MethodHookParam p){if(!p.hasThrowable()&&main()&&p.thisObject instanceof View view)observe(view);}});ownerType=owner;iconType=icon;ready=true;}catch(Throwable unavailable){ready=false;}}
