 private static boolean eligible(ViewGroup owner){if(!owner.getClass().getName().equals(OWNER)||!owner.isAttachedToWindow()||XposedHelpers.getObjectField(owner,"mIsolatedIcon")!=null)return false;View view=owner;for(int n=0;n<16&&view!=null;n++){if(view.getClass().getName().equals(ROOT))return true;view=view.getParent() instanceof View parent?parent:null;}return false;}
 static void begin(int counter,int maximum){if(!main()||counter<0||counter>1||maximum<0||maximum>8)throw new IllegalArgumentException();if(!end())throw new IllegalStateException();count=counter;limit=maximum;draws=0;if(count==0&&limit==0)return;if(!ready||failed)throw new IllegalStateException("Notification icons unavailable");long ticket=++generation;
  try{Class<?> ownerClass=ownerType,iconClass=iconType;
   if(limit!=0)hooks.add(XposedBridge.hookMethod(ownerClass.getDeclaredMethod("shouldForceOverflow",int.class,int.class,float.class,int.class),new XC_MethodHook(){@Override protected void beforeHookedMethod(MethodHookParam p){if(!active||failed||!main()||generation!=ticket||!(p.thisObject instanceof ViewGroup owner))return;try{if(eligible(owner)){int stock=(Integer)p.args[3];p.args[3]=stock<0?limit:Math.min(stock,limit);}}catch(Throwable unavailable){failed=true;}}}));
   if(count!=0)hooks.add(XposedBridge.hookMethod(iconClass.getDeclaredMethod("onDraw",Canvas.class),new XC_MethodHook(){@Override protected void beforeHookedMethod(MethodHookParam p){if(!active||failed||!main()||generation!=ticket||!(p.thisObject instanceof View icon)||!(icon.getParent() instanceof ViewGroup owner))return;try{if(!eligible(owner)||!icon.getClass().getName().equals(ICON)||!Boolean.TRUE.equals(XposedHelpers.callMethod(icon,"isNotification"))||((Number)XposedHelpers.callMethod(icon,"getVisibleState")).intValue()!=1)return;Object raw=XposedHelpers.getObjectField(owner,"mIconStates");if(!(raw instanceof Map<?,?> states))return;int hidden=0;for(int n=0;n<owner.getChildCount();n++){View child=owner.getChildAt(n);if(!child.getClass().getName().equals(ICON)||!Boolean.TRUE.equals(XposedHelpers.callMethod(child,"isNotification"))||Boolean.TRUE.equals(XposedHelpers.callMethod(child,"isIconBlocked")))continue;Object state=states.get(child);if(state!=null&&!Boolean.TRUE.equals(XposedHelpers.getObjectField(state,"hidden"))&&((Number)XposedHelpers.getObjectField(state,"iconAppearAmount")).floatValue()>0&&((Number)XposedHelpers.getObjectField(state,"visibleState")).intValue()!=0)hidden++;}if(hidden<1||icon.getWidth()<=0||icon.getHeight()<=0)return;
    float appearance=((Number)XposedHelpers.getObjectField(icon,"mDotAppearAmount")).floatValue();if(!Float.isFinite(appearance)||appearance<=0)return;int color=((Number)XposedHelpers.getObjectField(icon,"mDecorColor")).intValue();Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);paint.setColor(color);paint.setAlpha(Math.round(Color.alpha(color)*Math.min(1f,appearance)));paint.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));paint.setTextAlign(Paint.Align.CENTER);paint.setTextSize(icon.getHeight()*.52f);String text=hidden>99?"99+":"+"+hidden;float width=icon.getWidth()*.95f,measured=paint.measureText(text);if(measured>width)paint.setTextSize(paint.getTextSize()*width/measured);Canvas c=(Canvas)p.args[0];int save=c.save();try{c.clipRect(0,0,icon.getWidth(),icon.getHeight());Paint.FontMetrics fm=paint.getFontMetrics();c.drawText(text,icon.getWidth()/2f,(icon.getHeight()-fm.ascent-fm.descent)/2f,paint);}finally{c.restoreToCount(save);}if(active&&generation==ticket){draws++;p.setResult(null);}
   }catch(Throwable unavailable){failed=true;}}}));active=true;refresh();
  }catch(Throwable unavailable){end();throw new IllegalStateException("Notification icon controls unavailable",unavailable);}
 }
 private static void refresh(){for(ViewGroup owner:new ArrayList<>(owners.keySet()))try{if(eligible(owner)){XposedHelpers.callMethod(owner,"updateState");owner.requestLayout();owner.invalidate();}}catch(Throwable unavailable){failed=true;}}
